///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name disclsviewer
 * @description disclsviewer 처리
 * @param {*} acptNo acptNo
 * @returns {void}
 * @hidden N
 */
scwin.disclsviewer = function (acptNo) {
    fn_examViewer((String(((dma_pageContext.get("DST_URL") ?? "")) == null ? '' : ((dma_pageContext.get("DST_URL") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("DST_URL") ?? "")) == null ? '' : ((dma_pageContext.get("DST_URL") ?? "")))), acptNo);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_examViewer — as-is 정의 없음(원본 JS 미제공 — 회신)
};
